@@ -0,0 +1,32 @@
+// Picks the response language from a request's Accept-Language header.
+import { LANGUAGES } from "../i18n/messages.js";
+
+function headerValue(headers, name) {
+  for (const [k, v] of Object.entries(headers ?? {})) {
+    if (k.toLowerCase() === name) return Array.isArray(v) ? v.join(",") : v;
+  }
+  return undefined;
+}
+
+/** The supported language the request's Accept-Language prefers (highest q, region tags ignored), else `fallback`. */
+export function requestLanguage(headers, fallback) {
+  const header = headerValue(headers, "accept-language");
+  if (typeof header !== "string") return fallback;
+  let best = null;
+  let bestQ = 0;
+  for (const part of header.split(",")) {
+    const [tag, ...params] = part.split(";").map((s) => s.trim());
+    const lang = tag.toLowerCase().split("-")[0];
+    if (!LANGUAGES.includes(lang)) continue;
+    let q = 1;
+    for (const p of params) {
+      const m = /^q\s*=\s*(.*)$/i.exec(p);
+      if (m) q = /^(0(\.\d{0,3})?|1(\.0{0,3})?)$/.test(m[1]) ? Number(m[1]) : 0;
+    }
+    if (q > bestQ) {
+      best = lang;
+      bestQ = q;
+    }
+  }
+  return best ?? fallback;
+}
